/**
 * Every score surface the byte-identity proof pins, computed from the golden
 * dataset. Legacy signal entries are captured POSITIONALLY (present, value,
 * weight) without their ids, because PR10 renames a signal id without moving
 * any number; the values are the claim, the label is not.
 */
export function captureGoldenScores(): unknown {
  const dataset = goldenDataset();
  const usage = utilizationByAsset(dataset);
  const legacy = (window?: DateWindow) =>
    scoreAssets(dataset, window).map((score) => ({
      id: score.asset.id,
      governedScore: score.governedScore,
      effectiveScore: score.effectiveScore,
      governed: score.governed,
      effective: score.effective,
      quadrant: score.quadrant,
      confidence: score.confidence,
      evidenceSufficient: score.evidenceSufficient,
      stale: score.stale,
      signals: score.signals.map((signal) => ({
        present: signal.present,
        value: signal.value,
        weight: signal.weight,
      })),
    }));
  const aes = dataset.assets.map((row) => {
    const result = scoreAssetDetailed(row, dataset, usage);
    return {
      id: row.id,
      assetEffectivenessScore: result.assetEffectivenessScore,
      evidenceConfidenceScore: result.evidenceConfidenceScore,
      evidenceConfidenceGrade: result.evidenceConfidenceGrade,
      effectivenessTier: result.effectivenessTier,
      observedWeight: result.observedWeight,
      missingSignals: result.missingSignals,
      signalScores: result.signalScores,
    };
  });
  return {
    legacyFull: legacy(),
    legacyWindowed: legacy(GOLDEN_WINDOW),
    aes,
    aesEffectiveRate: aesEffectiveRate(dataset),
    aesEffectiveRateWindowed: aesEffectiveRate(dataset, GOLDEN_WINDOW),
    effectiveAssetRate: effectiveAssetRate(dataset),
    classificationCounts: classificationCounts(dataset),
  };
}
